    if(s.possessionLocks){auto buff=definitions().field(s.ability,"AbilityData","BuffID"+std::to_string(s.level));if(buff.size()!=9 || buff[4]!=',' || s.secondary<0 || s.secondary>100)throw std::runtime_error("Channelled possession requires its source protection buffs and damage factor");s.buff=ObjectData::code(buff.substr(0,4));s.guardBuff=ObjectData::code(buff.substr(5,4));s.possessionDamage=s.secondary;auto flag=[&](const char* key){auto value=field(key);if(value!=0 && value!=1)throw std::runtime_error("Invalid source possession protection flag");return value!=0;};s.controlInvulnerable=flag("DataC");s.controlMagicImmune=flag("DataD");for(auto id:{s.buff,s.guardBuff}){auto model=definitions().field(id,"Profile","TargetArt");if(!model.empty() && model!="_")s.visualModels.push_back(model);}}
